ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS registration_category text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS avatar_path text;
ALTER TABLE public.profiles ADD CONSTRAINT profiles_registration_category_valid CHECK (registration_category IS NULL OR registration_category IN ('client','professional','supplier','affiliate'));
UPDATE public.profiles p SET registration_category = COALESCE((SELECT CASE a.kind::text WHEN 'professional' THEN 'professional' WHEN 'supplier' THEN 'supplier' ELSE 'affiliate' END FROM public.partner_applications a WHERE a.user_id=p.user_id ORDER BY a.created_at LIMIT 1), CASE p.account_type::text WHEN 'professional' THEN 'professional' WHEN 'creator' THEN 'affiliate' WHEN 'partner' THEN 'supplier' ELSE NULL END) WHERE registration_category IS NULL;
CREATE POLICY "Admins read all profiles" ON public.profiles FOR SELECT TO authenticated USING (public.is_admin());
CREATE OR REPLACE FUNCTION public.create_registration_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(user_id,full_name,phone,city,registration_category) VALUES(NEW.id,COALESCE(left(NEW.raw_user_meta_data->>'full_name',120),''),left(NEW.raw_user_meta_data->>'phone',30),left(NEW.raw_user_meta_data->>'city',80),CASE WHEN NEW.raw_user_meta_data->>'registration_category' IN ('client','professional','supplier','affiliate') THEN NEW.raw_user_meta_data->>'registration_category' ELSE NULL END) ON CONFLICT(user_id) DO NOTHING; RETURN NEW; END; $$;
CREATE TRIGGER arqeco_registration_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_registration_profile();
INSERT INTO public.profiles(user_id,full_name) SELECT u.id,COALESCE(left(u.raw_user_meta_data->>'full_name',120),'') FROM auth.users u WHERE NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.user_id=u.id);
CREATE OR REPLACE FUNCTION public.admin_list_registrants() RETURNS TABLE(user_id uuid,email text,full_name text,phone text,city text,category text,avatar_path text,created_at timestamptz,email_confirmed boolean,application_status text) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Forbidden'; END IF; RETURN QUERY SELECT u.id,u.email::text,p.full_name,p.phone,p.city,p.registration_category,p.avatar_path,u.created_at,(u.email_confirmed_at IS NOT NULL),(SELECT a.status::text FROM public.partner_applications a WHERE a.user_id=u.id ORDER BY a.created_at DESC LIMIT 1) FROM auth.users u LEFT JOIN public.profiles p ON p.user_id=u.id ORDER BY u.created_at DESC; END; $$;
REVOKE ALL ON FUNCTION public.admin_list_registrants() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_list_registrants() TO authenticated,service_role;
CREATE TABLE public.diagnosticos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,project_id uuid REFERENCES public.projects(id),tipo_ambiente text NOT NULL CHECK(tipo_ambiente IN ('residencial','corporativo','comercial','terapeutico','hotelaria')),imagem_original_url text,imagem_transformada_url text,respostas jsonb NOT NULL DEFAULT '{}',resultado jsonb,status text NOT NULL DEFAULT 'processando' CHECK(status IN ('processando','concluido','erro')),nivel smallint,indice_regeneracao smallint,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.diagnosticos TO authenticated;
GRANT ALL ON public.diagnosticos TO service_role;
ALTER TABLE public.diagnosticos ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owners manage dossiers" ON public.diagnosticos FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE POLICY "Admins read dossiers" ON public.diagnosticos FOR SELECT TO authenticated USING(public.is_admin());
CREATE INDEX diagnosticos_user_created ON public.diagnosticos(user_id,created_at DESC);
CREATE TRIGGER diagnosticos_updated_at BEFORE UPDATE ON public.diagnosticos FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TABLE public.feedbacks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,diagnostico_id uuid REFERENCES public.diagnosticos(id),nota smallint CHECK(nota BETWEEN 1 AND 5),mensagem text NOT NULL CHECK(length(mensagem) BETWEEN 3 AND 2000),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.feedbacks TO authenticated;
GRANT ALL ON public.feedbacks TO service_role;
ALTER TABLE public.feedbacks ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owners read feedback" ON public.feedbacks FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_admin());
CREATE POLICY "Owners submit feedback" ON public.feedbacks FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND (diagnostico_id IS NULL OR EXISTS(SELECT 1 FROM public.diagnosticos d WHERE d.id=diagnostico_id AND d.user_id=auth.uid())));
CREATE TABLE public.eco_import_identities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_user_id uuid NOT NULL UNIQUE,email text NOT NULL,auth_user_id uuid,verified_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.eco_import_identities TO service_role;
ALTER TABLE public.eco_import_identities ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.eco_historical_access(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_user_id uuid NOT NULL,stripe_session_id text UNIQUE,ambiente text,expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.eco_historical_access TO service_role;
ALTER TABLE public.eco_historical_access ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.credit_internal_dossier_referral() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_email text; v_aff uuid; BEGIN IF NEW.status <> 'concluido' OR (TG_OP='UPDATE' AND OLD.status='concluido') THEN RETURN NEW; END IF; SELECT lower(trim(u.email)) INTO v_email FROM auth.users u WHERE u.id=NEW.user_id AND u.email_confirmed_at IS NOT NULL; IF v_email IS NULL THEN RETURN NEW; END IF; SELECT a.affiliate_id INTO v_aff FROM public.referral_attributions a JOIN public.referral_links l ON l.id=a.link_id WHERE a.referred_user_id=NEW.user_id AND l.plan_slug='start' AND a.affiliate_id<>NEW.user_id AND public.is_approved_affiliate(a.affiliate_id); IF v_aff IS NULL OR EXISTS(SELECT 1 FROM auth.users WHERE id=v_aff AND lower(trim(email))=v_email) THEN RETURN NEW; END IF; INSERT INTO public.eco_ledger(user_id,amount,reason,ref) VALUES(v_aff,20,'Dossiê Eco-Holístico gerado por indicação','start:'||v_email) ON CONFLICT(ref) DO NOTHING; RETURN NEW; END; $$;
CREATE TRIGGER credit_internal_dossier_referral AFTER INSERT OR UPDATE OF status ON public.diagnosticos FOR EACH ROW EXECUTE FUNCTION public.credit_internal_dossier_referral();
CREATE POLICY "Owners upload dossier images" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='ambientes' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY "Owners read dossier images" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='ambientes' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.is_admin()));
CREATE POLICY "Owners manage profile photos" ON storage.objects FOR ALL TO authenticated USING(bucket_id='profile-photos' AND (storage.foldername(name))[1]=auth.uid()::text) WITH CHECK(bucket_id='profile-photos' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY "Admins read profile photos" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='profile-photos' AND public.is_admin());